-- Шаг 49: страница «О нас» (RO, ресурс 102) — тексты «Вопросов и ответов» дословно из румынского макета пользователя
-- (TV migx_questions, id 37). Заголовок блока (TV 65) не меняется: «Răspunsuri la întrebări frecvente», как на всём сайте.
-- Откат: вернуть значение TV 37 ресурса 102 из патча stage-lbar-47-about.sql.
UPDATE Impulse_Digital_X_site_tmplvar_contentvalues SET value = '[{"MIGX_id": "1", "questions-title": "Cine efectuează procedurile în studioul Lbar?", "questions-text": "<p>Procedurile sunt realizate de masteri din două categorii: TOP-Master, cu peste 5 ani de experiență și certificate internaționale, și TOP-Trainer, master acreditat cu peste 8 ani de experiență. Studioul a fost fondat de Ksenia Kobilianskaia, Master Trainer internațional.</p>"}, {"MIGX_id": "2", "questions-title": "Cât durează o procedură?", "questions-text": "<p>Între o oră și o oră și jumătate, în funcție de zonă. Retușul durează aproximativ o oră.</p>"}, {"MIGX_id": "3", "questions-title": "Pot învăța micropigmentarea la Lbar?", "questions-text": "<p>Da. Școala Lbar a pregătit peste 400 de masteri, care lucrează astăzi în mai multe țări. Cursurile se bazează pe metoda proprie PM Control, creată de Ksenia Kobilianskaia.</p>"}, {"MIGX_id": "4", "questions-title": "Unde se află studioul din București?", "questions-text": "<p>Strada Polonă 92, Sector 1, la 4 minute de metroul Ștefan cel Mare. Program: luni–duminică, 9:00–20:00, doar cu programare.</p>"}]' WHERE tmplvarid = 37 AND contentid = 102;
